INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 6, 'theory', 'Quiz: Two Pointers');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 6, 0, 'Sorted array, looking for a pair with sum 10. The left and right pointers currently give 14. What do we do?', '["Move the left pointer right", "Move the right pointer left", "Move both", "Start over with a different pair"]', 1, 'The sum is too big, and the only way to reduce it is to take a smaller right element. The right element paired with any left one gives at least 14, so it can be discarded forever.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 6, 1, 'In the container with water problem you need to move one of the pointers. Which one?', '["The one with the taller wall", "The one with the shorter wall", "Always the left one", "The one farther from the middle"]', 1, 'The area is limited by the shorter wall. Moving the taller one reduces the width without raising the limiting height, so no improvement is possible. Move the shorter one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 6, 2, 'Why does the technique of two pointers moving toward each other for a sum not work on an unsorted array?', '["Because of overflow when adding", "It is not guaranteed that a pointer move changes the sum in the needed direction", "You cannot read an array from the end", "The complexity grows to exponential"]', 1, 'The reasoning "too big, so move the right one" relies on larger values standing on the right. Without sorting it proves nothing, and the answer can be lost.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 6, 3, 'In the zero-sum triples problem, why do we skip repeated values of the first element?', '["To speed up the sort", "To avoid identical triples in the answer", "To keep the pointers inside the array bounds", "To avoid overflowing the stack"]', 1, 'If the first element repeats the previous one, the same pairs will be found for it and the triples will be duplicated. The skip is done right after processing, with a bounds check.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 6, 4, 'In the Dutch national flag problem (0, 1, 2) the middle pointer met a two and swapped it with the right boundary. Why does it not move forward?', '["That is a mistake: it should move", "An element that has not been examined yet is now in that place", "The right boundary points to a zero", "The array is already sorted"]', 1, 'The element that came from the right has not been sorted yet, so mid stays and only the right boundary moves. With a zero, on the other hand, an already checked element lies on the left, so there we move both.');
